-- ================================================================
-- Dedup index for the new 'urdu-hadith' domain (hadeed-urdu dataset:
-- D:\EEData\hadith\hadeed_urdu_excel.csv, regenerated by
-- scripts/convert_excel_to_csv.py with a proper JSONB citation_ref).
--
-- Mirrors scholarly_documents_hadith_uidx (20260518080658_....sql), which is
-- scoped WHERE domain = 'hadith-json' and therefore does NOT catch repeats
-- within this new domain -- without this index, re-running the loader would
-- fall through to the slow global content-hash uniqueness check for every
-- one of the 37,154 rows.
-- ================================================================

CREATE UNIQUE INDEX IF NOT EXISTS scholarly_documents_urdu_hadith_uidx
  ON public.scholarly_documents (
    (citation_ref->>'collection'),
    (citation_ref->>'hadith_number')
  )
  WHERE domain = 'urdu-hadith'
    AND citation_ref->>'collection' IS NOT NULL
    AND citation_ref->>'hadith_number' IS NOT NULL;
